import torch
import torch_npu

def run(query: torch.Tensor, key: torch.Tensor, weights: torch.Tensor, actual_seq_lengths_query=None, actual_seq_lengths_key=None, block_table=None, layout_query='BSND', layout_key='BSND', sparse_count=2048, sparse_mode=3, pre_tokens=None, next_tokens=None, return_value=False):
    if pre_tokens is None:
        pre_tokens = (1 << 63) - 1
    if next_tokens is None:
        next_tokens = (1 << 63) - 1
    if layout_query is None:
        layout_query = 'BSND'
    if layout_key is None:
        layout_key = 'BSND'
    if sparse_count is None:
        sparse_count = 2048
    if sparse_mode is None:
        sparse_mode = 3
    if return_value is None:
        return_value = False
    if isinstance(actual_seq_lengths_query, list):
        actual_seq_lengths_query = torch.tensor(actual_seq_lengths_query, dtype=torch.int32, device=query.device)
    if isinstance(actual_seq_lengths_key, list):
        actual_seq_lengths_key = torch.tensor(actual_seq_lengths_key, dtype=torch.int32, device=key.device)
    if layout_key == 'PA_BSND':
        sparse_indices, _ = torch_npu.npu_lightning_indexer(
            query, key, weights,
            actual_seq_lengths_query=actual_seq_lengths_query,
            actual_seq_lengths_key=actual_seq_lengths_key,
            block_table=block_table, layout_query=layout_query, layout_key=layout_key,
            sparse_count=sparse_count, sparse_mode=sparse_mode,
            pre_tokens=pre_tokens, next_tokens=next_tokens,
            return_value=False)
        sparse_values = torch.zeros(
            sparse_indices.shape, dtype=torch.int32, device=sparse_indices.device)
    else:
        sparse_indices, sparse_values_raw = torch_npu.npu_lightning_indexer(
            query, key, weights,
            actual_seq_lengths_query=actual_seq_lengths_query,
            actual_seq_lengths_key=actual_seq_lengths_key,
            block_table=block_table, layout_query=layout_query, layout_key=layout_key,
            sparse_count=sparse_count, sparse_mode=sparse_mode,
            pre_tokens=pre_tokens, next_tokens=next_tokens,
            return_value=True)
        if not return_value:
            sparse_values = torch.zeros(
                sparse_indices.shape, dtype=torch.int32, device=sparse_indices.device)
        else:
            sparse_values = sparse_values_raw.to(torch.int32)
    perm = torch.argsort(sparse_indices, dim=-1, stable=True)
    sparse_indices = torch.gather(sparse_indices, -1, perm)
    if return_value:
        sparse_values = torch.gather(sparse_values, -1, perm)
    return (sparse_indices, sparse_values)
